import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Checkbox,
  Chip,
  CircularProgress,
  FormControl,
  FormControlLabel,
  FormGroup,
  Grid,
  InputLabel,
  LinearProgress,
  List,
  ListItem,
  ListItemText,
  MenuItem,
  Select,
  Stack,
  Step,
  StepLabel,
  Stepper,
  TextField,
  Typography,
} from '@mui/material';
import AutoAwesomeIcon from '@mui/icons-material/AutoAwesome';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import SaveIcon from '@mui/icons-material/Save';
import ApiService from '../../services/api';
import Scope3Cat5WastePanel from '../operations/Scope3Cat5WastePanel';
import { useResponsiveStepperOrientation } from '../../hooks/useResponsiveStepperOrientation';

const MATERIAL_OPTIONS = [
  { id: 'plastic_packaging', label: 'Plastic packaging', hint: 'Bottles, wraps, pouches' },
  { id: 'e_waste', label: 'Electronics waste', hint: 'PCBs, wires, gadgets' },
  { id: 'batteries', label: 'Batteries', hint: 'Lead-acid, lithium, etc.' },
  { id: 'tyres', label: 'Old tyres', hint: 'Vehicle or industrial' },
  { id: 'used_oil', label: 'Used oil', hint: 'Lubricants, process oil' },
  { id: 'other', label: 'Other waste you must take back', hint: 'Ask your consultant if unsure' },
];

const PRODUCER_TYPES = [
  { id: 'manufacturer', label: 'I manufacture the product' },
  { id: 'brand_owner', label: 'I sell under my own brand' },
  { id: 'importer', label: 'I import these goods' },
  { id: 'bulk_consumer', label: 'I buy and use large volumes' },
  { id: 'not_applicable', label: 'This does not apply to my unit' },
];

const STEP_LABELS = ['Does this apply?', 'Add your basics', 'Enter waste amounts'];

const SECTION_LABELS: Record<string, string> = {
  applicability: 'Does EPR apply?',
  registrationEvidence: 'Your registration & papers',
  wasteRecyclingBehaviour: 'Recycling vs disposal',
};

const ITEM_TITLE_OVERRIDES: Record<string, string> = {
  epr_applicability_declared: 'Tell us if take-back rules apply to you',
  material_categories_mapped: 'Choose the waste types you handle',
  cbam_separation_acknowledged: 'Keep this separate from EU carbon tax (CBAM)',
  cpcb_registration: 'Add your government EPR registration number',
  pro_or_recycler_link: 'Name your recycler or take-back partner',
  certificate_evidence: 'Upload or record EPR certificates',
  cat5_waste_inventory: 'Enter how much waste you generated',
  recycling_vs_disposal: 'Split recycled vs dumped waste',
  recycling_targets: 'Set recycling target vs achieved tonnes',
};

type ChecklistItem = {
  id?: string;
  title?: string;
  description?: string;
  status?: string;
};

type GapChecklist = {
  applicable?: boolean;
  overallReadinessScore?: number | null;
  scopeNote?: string;
  sections?: Record<string, { readinessScore?: number; items?: ChecklistItem[] }>;
  priorityActions?: Array<{ action?: string; detail?: string; priority?: string; gapId?: string }>;
  wasteSignals?: {
    totalTonnes?: number;
    recyclingTonnes?: number;
    recyclingSharePct?: number | null;
    transactionCount?: number;
  };
  cbamRelationship?: { note?: string };
};

type EprProfileForm = {
  applicable: boolean | null;
  producerType: string;
  materialCategories: string[];
  cpcbRegistrationId: string;
  proName: string;
  targetFy: string;
  notes: string;
};

type EprCompliancePanelProps = {
  period?: string;
  initialProfile?: Partial<EprProfileForm> & {
    certificates?: unknown[];
    recyclingTargets?: unknown[];
  };
  onSaved?: () => void;
};

const friendlyItemTitle = (item: ChecklistItem): string => {
  if (item.id && ITEM_TITLE_OVERRIDES[item.id]) {
    return ITEM_TITLE_OVERRIDES[item.id];
  }
  return item.title || 'Next task';
};

const readinessLabel = (score: number | null | undefined, applicable?: boolean): string => {
  if (applicable === false) return 'Not needed for your unit';
  const value = Number(score || 0);
  if (value >= 75) return 'Looking good';
  if (value >= 40) return 'Getting ready';
  return 'Needs a few details';
};

const EprCompliancePanel: React.FC<EprCompliancePanelProps> = ({
  period = 'annual',
  initialProfile,
  onSaved,
}) => {
  const { orientation, alternativeLabel } = useResponsiveStepperOrientation();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [orchestrating, setOrchestrating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [checklist, setChecklist] = useState<GapChecklist | null>(null);
  const [activeStep, setActiveStep] = useState(0);
  const [form, setForm] = useState<EprProfileForm>({
    applicable: null,
    producerType: '',
    materialCategories: [],
    cpcbRegistrationId: '',
    proName: '',
    targetFy: '',
    notes: '',
  });

  const loadChecklist = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await ApiService.getEprGapClosureChecklist({ period });
      setChecklist((res?.data?.checklist as GapChecklist) || null);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Could not load your waste take-back checklist');
    } finally {
      setLoading(false);
    }
  }, [period]);

  useEffect(() => {
    if (initialProfile) {
      setForm({
        applicable: typeof initialProfile.applicable === 'boolean' ? initialProfile.applicable : null,
        producerType: String(initialProfile.producerType || ''),
        materialCategories: Array.isArray(initialProfile.materialCategories)
          ? initialProfile.materialCategories.map(String)
          : [],
        cpcbRegistrationId: String(initialProfile.cpcbRegistrationId || ''),
        proName: String(initialProfile.proName || ''),
        targetFy: String(initialProfile.targetFy || ''),
        notes: String(initialProfile.notes || ''),
      });
    }
  }, [initialProfile]);

  useEffect(() => {
    void loadChecklist();
  }, [loadChecklist]);

  useEffect(() => {
    if (!form.producerType) {
      setActiveStep(0);
      return;
    }
    if (form.producerType === 'not_applicable') {
      setActiveStep(0);
      return;
    }
    if (!form.cpcbRegistrationId && form.materialCategories.length === 0) {
      setActiveStep(1);
      return;
    }
    setActiveStep(2);
  }, [form.producerType, form.cpcbRegistrationId, form.materialCategories.length]);

  const toggleMaterial = (id: string) => {
    setForm((prev) => {
      const has = prev.materialCategories.includes(id);
      return {
        ...prev,
        materialCategories: has
          ? prev.materialCategories.filter((item) => item !== id)
          : [...prev.materialCategories, id],
      };
    });
  };

  const saveProfile = async () => {
    setSaving(true);
    setError(null);
    setMessage(null);
    try {
      await ApiService.updateEprProfile({
        applicable: form.producerType === 'not_applicable' ? false : form.applicable ?? true,
        producerType: form.producerType || null,
        materialCategories: form.materialCategories,
        cpcbRegistrationId: form.cpcbRegistrationId,
        proName: form.proName,
        targetFy: form.targetFy,
        notes: form.notes,
      });
      setMessage('Saved. Your checklist will update in a moment.');
      await loadChecklist();
      onSaved?.();
      if (form.producerType && form.producerType !== 'not_applicable') {
        setActiveStep((prev) => Math.min(2, prev + 1));
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Could not save. Try again.');
    } finally {
      setSaving(false);
    }
  };

  const runAgents = async () => {
    setOrchestrating(true);
    setError(null);
    setMessage(null);
    try {
      const res = await ApiService.orchestrateEprReadiness({ period, applyChanges: true });
      const data = res?.data as {
        message?: string;
        readinessSnapshot?: { readinessScore?: number };
      };
      const score = data?.readinessSnapshot?.readinessScore;
      setMessage(
        score != null
          ? `Suggested next fields filled where possible. Progress is now ${score}%.`
          : 'Suggested next fields filled where possible.'
      );
      await loadChecklist();
      onSaved?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Could not suggest next steps. Try again.');
    } finally {
      setOrchestrating(false);
    }
  };

  const wasteSignals = checklist?.wasteSignals;
  const openItems = useMemo(
    () => Object.values(checklist?.sections || {})
      .flatMap((section) => section.items || [])
      .filter((item) => item.status !== 'complete' && item.id !== 'cbam_separation_acknowledged'),
    [checklist]
  );
  const nextAction = checklist?.priorityActions?.[0] || null;
  const score = checklist?.overallReadinessScore ?? 0;
  const notApplicable = form.producerType === 'not_applicable' || checklist?.applicable === false;

  if (loading && !checklist) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
        <CircularProgress size={28} />
      </Box>
    );
  }

  return (
    <Stack spacing={2}>
      <Card variant="outlined" sx={{ bgcolor: 'action.hover' }}>
        <CardContent>
          <Typography variant="h6" sx={{ fontWeight: 700, mb: 0.5 }}>
            Waste take-back (EPR) — simple setup
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            If you make, brand, or import products that create packaging, e-waste, batteries, tyres, or oil waste,
            India may ask you to arrange take-back and recycling. Fill three short steps below.
          </Typography>
          <Stepper activeStep={activeStep} orientation={orientation} alternativeLabel={alternativeLabel}>
            {STEP_LABELS.map((label) => (
              <Step key={label}>
                <StepLabel>{label}</StepLabel>
              </Step>
            ))}
          </Stepper>
        </CardContent>
      </Card>

      {error ? <Alert severity="error">{error}</Alert> : null}
      {message ? <Alert severity="success">{message}</Alert> : null}

      <Card variant="outlined">
        <CardContent>
          <Stack
            direction={{ xs: 'column', sm: 'row' }}
            spacing={2}
            alignItems={{ xs: 'stretch', sm: 'center' }}
            justifyContent="space-between"
          >
            <Box sx={{ flex: 1 }}>
              <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 0.5 }}>
                <Typography variant="subtitle2" color="text.secondary">
                  Your progress
                </Typography>
                <Chip
                  size="small"
                  color={notApplicable ? 'default' : score >= 75 ? 'success' : score >= 40 ? 'warning' : 'default'}
                  label={readinessLabel(score, notApplicable ? false : checklist?.applicable)}
                />
              </Stack>
              <Typography variant="h4" sx={{ fontWeight: 700 }}>
                {notApplicable ? '—' : `${score}%`}
              </Typography>
              <LinearProgress
                variant="determinate"
                value={notApplicable ? 0 : Math.min(100, score)}
                sx={{ height: 8, borderRadius: 1, my: 1, maxWidth: 360 }}
              />
              <Typography variant="body2" color="text.secondary">
                {Number(wasteSignals?.transactionCount || 0) > 0
                  ? `Waste logged: ${wasteSignals?.totalTonnes ?? 0} tonnes · Recycled: ${wasteSignals?.recyclingTonnes ?? 0} tonnes`
                  : 'No waste amounts logged yet — use step 3 when ready.'}
              </Typography>
              {nextAction && !notApplicable ? (
                <Typography variant="body2" sx={{ mt: 1, fontWeight: 600 }}>
                  Next: {ITEM_TITLE_OVERRIDES[nextAction.gapId || ''] || nextAction.action}
                </Typography>
              ) : null}
            </Box>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
              <Button
                variant="contained"
                startIcon={orchestrating ? <CircularProgress size={16} color="inherit" /> : <AutoAwesomeIcon />}
                onClick={() => void runAgents()}
                disabled={orchestrating || notApplicable}
              >
                Suggest what to fill
              </Button>
              <Button variant="outlined" onClick={() => setActiveStep(notApplicable ? 0 : Math.min(2, openItems.length ? 1 : 2))}>
                Continue setup
              </Button>
            </Stack>
          </Stack>
        </CardContent>
      </Card>

      <Card variant="outlined">
        <CardContent>
          <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
            Step 1 — Does this apply to you?
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Pick the option that best matches your business. If unsure, choose manufacturer and we will guide you.
          </Typography>
          <FormControl fullWidth size="small" sx={{ maxWidth: 420 }}>
            <InputLabel>Your role</InputLabel>
            <Select
              label="Your role"
              value={form.producerType}
              onChange={(e) => setForm((prev) => ({
                ...prev,
                producerType: String(e.target.value),
                applicable: e.target.value === 'not_applicable' ? false : true,
              }))}
            >
              {PRODUCER_TYPES.map((item) => (
                <MenuItem key={item.id} value={item.id}>{item.label}</MenuItem>
              ))}
            </Select>
          </FormControl>
          {notApplicable ? (
            <Alert severity="info" sx={{ mt: 2 }}>
              Fine — you can skip the rest. If a buyer later asks for waste take-back proof, come back and change this.
            </Alert>
          ) : null}
        </CardContent>
      </Card>

      {!notApplicable ? (
        <>
          <Card variant="outlined">
            <CardContent>
              <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
                Step 2 — Add your basics
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                Use details from your CPCB / state board portal or from your recycler. Leave blank if you do not have them yet.
              </Typography>
              <Grid container spacing={2}>
                <Grid item xs={12}>
                  <Typography variant="body2" sx={{ fontWeight: 600, mb: 0.5 }}>
                    What waste types do you put on the market?
                  </Typography>
                  <FormGroup>
                    {MATERIAL_OPTIONS.map((item) => (
                      <FormControlLabel
                        key={item.id}
                        control={(
                          <Checkbox
                            checked={form.materialCategories.includes(item.id)}
                            onChange={() => toggleMaterial(item.id)}
                          />
                        )}
                        label={(
                          <Box>
                            <Typography variant="body2">{item.label}</Typography>
                            <Typography variant="caption" color="text.secondary">{item.hint}</Typography>
                          </Box>
                        )}
                      />
                    ))}
                  </FormGroup>
                </Grid>
                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    size="small"
                    label="EPR registration number (if you have one)"
                    helperText="From CPCB or your state pollution control board"
                    value={form.cpcbRegistrationId}
                    onChange={(e) => setForm((prev) => ({ ...prev, cpcbRegistrationId: e.target.value }))}
                  />
                </Grid>
                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    size="small"
                    label="Recycler or take-back partner name"
                    helperText="Company that collects or recycles your waste"
                    value={form.proName}
                    onChange={(e) => setForm((prev) => ({ ...prev, proName: e.target.value }))}
                  />
                </Grid>
                <Grid item xs={12} md={4}>
                  <TextField
                    fullWidth
                    size="small"
                    label="Filing year"
                    placeholder="FY2025-26"
                    value={form.targetFy}
                    onChange={(e) => setForm((prev) => ({ ...prev, targetFy: e.target.value }))}
                  />
                </Grid>
                <Grid item xs={12} md={8}>
                  <TextField
                    fullWidth
                    size="small"
                    label="Any note for your team"
                    value={form.notes}
                    onChange={(e) => setForm((prev) => ({ ...prev, notes: e.target.value }))}
                  />
                </Grid>
                <Grid item xs={12}>
                  <Button
                    variant="contained"
                    startIcon={saving ? <CircularProgress size={16} color="inherit" /> : <SaveIcon />}
                    onClick={() => void saveProfile()}
                    disabled={saving || !form.producerType}
                  >
                    Save and continue
                  </Button>
                </Grid>
              </Grid>
            </CardContent>
          </Card>

          <Card variant="outlined">
            <CardContent>
              <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
                Step 3 — Enter waste amounts
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                Add how many tonnes went to recycling, landfill, or other routes this year. This also helps your carbon report.
              </Typography>
              <Scope3Cat5WastePanel
                msmeFriendly
                title="Waste amounts by what happened to it"
                helperText="Example: 2 tonnes recycled scrap, 0.5 tonnes landfill. Use your recycler slips or weighbridge notes."
              />
            </CardContent>
          </Card>
        </>
      ) : (
        <Box>
          <Button
            variant="outlined"
            startIcon={saving ? <CircularProgress size={16} /> : <SaveIcon />}
            onClick={() => void saveProfile()}
            disabled={saving || !form.producerType}
          >
            Save “does not apply”
          </Button>
        </Box>
      )}

      <Accordion variant="outlined" disableGutters>
        <AccordionSummary expandIcon={<ExpandMoreIcon />}>
          <Box>
            <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
              What is still missing? ({openItems.length})
            </Typography>
            <Typography variant="caption" color="text.secondary">
              Open only if you want the full checklist
            </Typography>
          </Box>
        </AccordionSummary>
        <AccordionDetails>
          <Stack spacing={2}>
            {Object.entries(checklist?.sections || {}).map(([key, section]) => (
              <Box key={key}>
                <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 0.5 }}>
                  <Typography variant="body2" sx={{ fontWeight: 700 }}>
                    {SECTION_LABELS[key] || key}
                  </Typography>
                  <Chip size="small" label={`${section.readinessScore ?? 0}%`} variant="outlined" />
                </Stack>
                <List dense disablePadding>
                  {(section.items || []).map((item) => (
                    <ListItem key={item.id || item.title} disableGutters>
                      <ListItemText
                        primary={(
                          <Stack direction="row" spacing={1} alignItems="center">
                            <Chip
                              size="small"
                              label={item.status === 'complete' ? 'Done' : 'To do'}
                              color={item.status === 'complete' ? 'success' : 'warning'}
                              variant="outlined"
                            />
                            <Typography variant="body2">{friendlyItemTitle(item)}</Typography>
                          </Stack>
                        )}
                        secondary={item.description}
                      />
                    </ListItem>
                  ))}
                </List>
              </Box>
            ))}
          </Stack>
        </AccordionDetails>
      </Accordion>

      <Accordion variant="outlined" disableGutters>
        <AccordionSummary expandIcon={<ExpandMoreIcon />}>
          <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
            Why this is not the same as EU carbon tax (CBAM)
          </Typography>
        </AccordionSummary>
        <AccordionDetails>
          <Typography variant="body2" color="text.secondary">
            {checklist?.cbamRelationship?.note
              || 'Waste take-back (EPR) proves you recycle or dispose responsibly in India. EU CBAM is about carbon inside exported goods. Keep them separate.'}
          </Typography>
        </AccordionDetails>
      </Accordion>
    </Stack>
  );
};

export default EprCompliancePanel;
